import{_ as c,o,c as a,a3 as n}from"./chunks/framework.DAK02U1-.js";const h=JSON.parse('{"title":"编译命令","description":"","frontmatter":{"head":[["meta",{"property":"og:title","content":"编译命令 | clice.io"}],["meta",{"property":"og:url","content":"https://docs.clice.io/zh/clice/cli/command"}],["meta",{"property":"og:image","content":"https://docs.clice.io/og.png"}],["meta",{"property":"og:image:width","content":"1200"}],["meta",{"property":"og:image:height","content":"630"}],["meta",{"property":"og:locale","content":"zh_CN"}],["link",{"rel":"canonical","href":"https://docs.clice.io/zh/clice/cli/command"}],["link",{"rel":"alternate","hreflang":"en","href":"https://docs.clice.io/clice/cli/command"}],["link",{"rel":"alternate","hreflang":"x-default","href":"https://docs.clice.io/clice/cli/command"}],["link",{"rel":"alternate","hreflang":"zh-CN","href":"https://docs.clice.io/zh/clice/cli/command"}]]},"headers":[],"relativePath":"zh/clice/cli/command.md","filePath":"zh/clice/cli/command.md","lastUpdated":1793393027000}'),i={name:"zh/clice/cli/command.md"};function t(l,e,s,d,r,p){return o(),a("div",null,[...e[0]||(e[0]=[n(`<h1 id="编译命令" tabindex="-1">编译命令 <a class="header-anchor" href="#编译命令" aria-label="Permalink to &quot;编译命令&quot;">​</a></h1><h2 id="概述" tabindex="-1">概述 <a class="header-anchor" href="#概述" aria-label="Permalink to &quot;概述&quot;">​</a></h2><p><code>clice command</code> 显示 clice 编译某个文件时所用的命令，也能把编译命令转换成这种命令，供其他工具读取。它读取编译数据库，并向数据库中指定的编译器查询；既不需要索引，也不需要服务器。</p><p><strong>用法</strong>：<code>clice command &lt;file&gt; [--workspace &lt;dir&gt;] [--configuration &lt;tag&gt;] [--json]</code></p><p><strong>用法</strong>：<code>clice command convert &lt;compile_commands.json&gt; [--workspace &lt;dir&gt;] [--configuration &lt;tag&gt;]</code></p><p><strong>用法</strong>：<code>clice command convert [--json] [--workspace &lt;dir&gt;] [--configuration &lt;tag&gt;] -- &lt;compiler&gt; &lt;arguments&gt;...</code></p><h2 id="文件的命令" tabindex="-1">文件的命令 <a class="header-anchor" href="#文件的命令" aria-label="Permalink to &quot;文件的命令&quot;">​</a></h2><p><code>clice command &lt;file&gt;</code> 列出编译数据库为该文件记录的每个条目，按构建给出的优先级排序；排在第一的就是编辑器编译该文件时使用的条目，除非用户另选一条。每个条目会显示它所在的数据库、条目的原文（<code>command</code> 字符串按 clice 的方式拆分），以及 clice 依据该条目编译文件时所用的命令：先用 <code>clice.toml</code> 的<a href="./../guide/configuration#rules">规则</a>修改条目，再交给条目指定的编译器解析，由编译器给出目标平台和系统头文件目录，作为一条 <code>-cc1</code> 命令的参数。这些目录中，有的存放着 clice 编译时看不到的文件：一是另一个编译器的内置头文件，clang 自己的内置头文件代替了它们（GCC 私有目录中的那些，或另一个 clang 的那些）；二是列表更靠后、那个编译器自己也永远读不到的同名副本。每个这样的目录各有一行 <code>hidden</code> 给出这些文件的数目（见<a href="./../design/command-resolve#toolchain-query">工具链查询</a>）。编译器无法查询时（没有安装，或拒绝了查询），错误信息会说明原因，此时显示的是 clang 自己的驱动代替该编译器读取的那条驱动级命令，与规则写上 <code>query_toolchain = false</code> 时相同：基于兼容版本 Clang 的工具读它，结果与 clice 一致。<code>--json</code> 则把同样的内容输出为一个 JSON 对象。</p><p>查找的数据库与编辑器为该文件加载的相同：即规则指定的数据库；若规则未指定，则是项目根目录、其直接子目录，以及该文件与根目录之间各级目录中的 <code>compile_commands.json</code>。没有自身条目的文件，例如头文件（编辑器借用包含它的源文件的命令来编译它），会报告为没有条目。</p><div class="language-console vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">console</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">$ clice command src/main.cpp</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">/home/me/project/build/compile_commands.json:</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  directory: /home/me/project/build</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  command:   /usr/bin/g++ -std=c++20 -O2 -Werror -o main.o -c ../src/main.cpp</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  resolved:  /usr/bin/g++ -cc1 -main-file-name main.cpp -triple x86_64-unknown-linux-gnu -O2 … -internal-isystem /usr/include/c++/13 … -std=c++20 … -x c++ /home/me/project/src/main.cpp</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  hidden:    112 of the files in /usr/lib/gcc/x86_64-linux-gnu/13/include</span></span></code></pre></div><p>列出了文件的条目时退出码为 0；文件不存在或没有数据库列出它时为 1；参数无法解析时为 2。</p><h2 id="转换命令" tabindex="-1">转换命令 <a class="header-anchor" href="#转换命令" aria-label="Permalink to &quot;转换命令&quot;">​</a></h2><p><code>clice command convert &lt;compile_commands.json&gt;</code>（也可以给出含有它的目录）输出这份数据库，并把其中每个条目的命令（<code>arguments</code> 或 <code>command</code>）替换为 clice 编译该条目文件时所用的 <code>arguments</code>（已按项目 <code>clice.toml</code> 中的规则修改）。条目保留 <code>file</code> 和 <code>output</code>；<code>directory</code> 写成绝对路径，相对路径以数据库所在目录为基准；其余字段不保留。clice 不编译的条目（例如汇编源文件）保留原来的命令。写出的命令略去了另一个编译器的内置头文件目录：这些目录中有被隐藏的文件，而命令无法表达这一点（见<a href="./../design/command-resolve#known-limitations">已知限制</a>）。<code>clice command convert -- &lt;compiler&gt; &lt;arguments&gt;...</code> 转换单条命令：这条命令在当前目录下运行，且只编译一个 C 系源文件；结果输出为一行命令，加上 <code>--json</code> 时则输出为一个数据库条目。</p><p>转换后的命令是 clice 所基于的 Clang 的 <code>-cc1</code> 命令，适用于基于兼容版本 Clang 的工具。编译器无法查询的命令则仍是驱动级命令，即 clang 自己的驱动代替该编译器读取的那条命令。</p><p>所有命令都转换成功时退出码为 0；有编译器无法查询时为 1，此时仍会输出已转换的结果，无法查询的命令输出为上述驱动级命令；数据库无法读取，或命令没有编译任何 C 系源文件、编译了多个时，同样为 1；参数无法解析时为 2。</p>`,15)])])}const g=c(i,[["render",t]]);export{h as __pageData,g as default};
